SELECT countIf(sticky) AS clicked_apply_in_1_min, countIf(opened) AS opened_new_form, countIf(cont) AS pressed_continue, countIf(role) AS picked_role, countIf(cv) AS chose_cv, countIf(cv AND last_body_apply > first_cv) AS clicked_apply_after_cv, countIf(cv AND last_body_apply > first_cv AND sticky) AS submitted_via_sticky, countIf(new_sub) AS new_form_tracked_submits, countIf(old_open) AS opened_old_form, countIf(old_sub) AS old_form_tracked_submits FROM (SELECT person_id, countIf(event = 'cta_click' AND properties.cta_name = 'apply_in_1_min') > 0 AS sticky, countIf(event = 'click_open_form' AND properties.form_name = 'join-betterhomes') > 0 AS opened, countIf(event = 'cta_click' AND properties.cta_name = 'continue') > 0 AS cont, countIf(event = 'cta_click' AND properties.cta_name IN ('sales_consultant', 'leasing_consultant', 'senior_sales_consultant', 'off_plan_consultant')) > 0 AS role, countIf(event = 'cta_click' AND properties.cta_name = 'choose_file') > 0 AS cv, minIf(timestamp, event = 'cta_click' AND properties.cta_name = 'choose_file') AS first_cv, maxIf(timestamp, event = 'cta_click' AND properties.cta_name = 'apply_now' AND properties.cta_location = 'join_our_team_body') AS last_body_apply, countIf(event = 'lead_join_our_team' AND properties.form_name = 'join-betterhomes') > 0 AS new_sub, countIf(event = 'click_open_form' AND properties.form_name = 'careers-schedule-call') > 0 AS old_open, countIf(event = 'lead_join_our_team' AND properties.form_name = 'careers-schedule-call') > 0 AS old_sub FROM events WHERE timestamp >= toDateTime('2026-11-04 17:25:00', 'Asia/Dubai') AND timestamp < now() AND properties.$pathname LIKE '/en/join-our-team%' AND event IN ('cta_click', 'click_open_form', 'lead_join_our_team') AND coalesce(properties.$virt_is_bot, false) = false GROUP BY person_id)